mapper.select:
SELECT id, shop_id AS shopId, category_name AS categoryName, sort, status, create_time, update_time
FROM dish_category
WHERE id = #{id}

mapper.update:
UPDATE dish_category
SET shop_id = #{category.shopId},
    category_name = #{category.categoryName},
    sort = #{category.sort},
    status = #{category.status}
WHERE id = #{id}
